        if (g_pStaticsArgsRingRefl) { removeResource(g_pStaticsArgsRingRefl); g_pStaticsArgsRingRefl = nullptr; }
        if (g_pStaticsInstRingRefl) { removeResource(g_pStaticsInstRingRefl); g_pStaticsInstRingRefl = nullptr; }
