        if (g_live.pCullShader)        { removeShader(R, g_live.pCullShader);        g_live.pCullShader = nullptr; }
        if (g_live.pCullParamsCbv)     { removeResource(g_live.pCullParamsCbv);      g_live.pCullParamsCbv = nullptr; }
