        if (g_live.pAtmosTransPipeline) { removePipeline(R, g_live.pAtmosTransPipeline);  g_live.pAtmosTransPipeline = nullptr; }
        if (g_live.pAtmosShShader)      { removeShader(R, g_live.pAtmosShShader);         g_live.pAtmosShShader = nullptr; }
